sealed class StoreGuard : DispatchProxy {
    private Store _store = null!;  private IPolicy _policy = null!;
    protected override object? Invoke(MethodInfo m, object?[]? args) {
        var who = InScope<ClaimsPrincipal>();
        if (!_policy.Allows(who, m)) throw new UnauthorizedAccessException(m.Name);
        return m.Invoke(_store, args);          // authorize, then delegate
    }
}
var guard = DispatchProxy.Create<IStore, StoreGuard>();   // callers see IStore, never Store
